(* [comment removed for export] *)
Lemma lp_lift K R M model LBX cr sp r fb cat p s str sm en k e M1 model1 s1 sm1 en1 k1 e1 cr1 M2 model2 s2 sm2 en2 k2 e2 cr2 scr' :
  PESCLPD.pctx L HI P K R M model LBX cr sp r fb cat p s str sm en k e ->
  PESCLPD.lrel L HI P R M model LBX cr sp fb s sm en k e M1 model1 s1 sm1 en1 k1 e1 cr1 ->
  0 <= scr' -> scr' + 128 <= 32768 ->
  L5C.hpres L LBX (sp - 128) scr' (PEC.W_crun AD EE fb) M1 M2 ->
  PMSP.src_step (PM.p_src s1) (PM.p_src s2) sm1 sm2 -> (e1 = true -> e2 = true) ->
  PMSP.credit_keep cr1 cr2 (PEC.pot_all L P s1 en1 k1) (PEC.pot_all L P s2 en2 k2) -> model_but_vm model1 model2 ->
  hi_heap HI (PEC.owned s2 en2 k2 ++ LBX) cr2 M2 (m_vmmaps model2) ->
  PESCLPD.lrel L HI P R M model LBX cr sp fb s sm en k e M2 model2 s2 sm2 en2 k2 e2 cr2 /\ L5C.stk (hl_sptop L) M2 sp 32768
  /\ (forall a n, sp - 128 <= a -> a + n <= fb + 16 -> L5C.agree_on M1 M2 a n) /\ (forall a n, fb + 32 <= a -> a + n <= fb + 56 -> L5C.agree_on M1 M2 a n)
